interface OrderObserver {
    void notify(String order);
}

class OrderSubject {
    private List<OrderObserver> observers = new ArrayList<>();

    public void register(OrderObserver observer) {
        observers.add(observer);
    }

    public void notifyObservers(String order) {
        for (OrderObserver observer : observers) {
            observer.notify(order);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        OrderSubject orderSubject = new OrderSubject();
        orderSubject.register(o -> System.out.println("Notified about order: " + o));

        String order = "ORD-001";
        orderSubject.notifyObservers(order);
        // anyone who subscribed gets notified automatically
    }
}

codes.cpp:
#include <bits/stdc++.h>
using namespace std;

class OrderSubject {
    vector<function<void(string)>> observers;
public:
    void registerObserver(function<void(string)> observer) {
        observers.push_back(observer);
    }

    void notifyObservers(const string& order) {
        for (auto& observer : observers) {
            observer(order);
        }
    }
};

int main() {
    OrderSubject orderSubject;
    orderSubject.registerObserver([](string o) { cout << "Notified about order: " << o << endl; });

    string order = "ORD-001";
    orderSubject.notifyObservers(order);
    // anyone who subscribed gets notified automatically
    return 0;
}

