#include <bits/stdc++.h>
using namespace std;

class StockPrice;

class StockPrice;

class StockObserver {
public:
    virtual void update(StockPrice& stockPrice) = 0;
    virtual ~StockObserver() = default;
};

class StockSubject {
public:
    virtual void registerObserver(StockObserver* observer) = 0;
    virtual void removeObserver(StockObserver* observer) = 0;
    virtual void notifyObservers() = 0;
    virtual ~StockSubject() = default;
};

class StockPrice : public StockSubject {
    string symbol;
    double price;
    vector<StockObserver*> observers;
public:
    void registerObserver(StockObserver* observer) override {
        observers.push_back(observer);
    }

    void removeObserver(StockObserver* observer) override {
        observers.erase(std::remove(observers.begin(), observers.end(), observer), observers.end());
    }

    void notifyObservers() override {
        for (auto observer : observers) {
            observer->update(*this);
        }
    }

    void priceUpdated(const string& symbol, double newPrice) {
        this->symbol = symbol;
        this->price = newPrice;

        cout << endl << "StockPrice: " << symbol << " updated to $" << newPrice << endl;
        notifyObservers();
    }

    string getSymbol() { return symbol; }
    double getPrice() { return price; }
};

int main() {
    StockPrice stock;
    stock.priceUpdated("AAPL", 178.50);
    return 0;
}

