public:
    virtual void registerObserver(StockObserver* observer) = 0;
    virtual void removeObserver(StockObserver* observer) = 0;
    virtual void notifyObservers() = 0;
    virtual ~StockSubject() = default;
};

class StockPrice : public StockSubject {
    string symbol;
    double price;
    vector<StockObserver*> observers;
public:
    void registerObserver(StockObserver* observer) override {
        observers.push_back(observer);
    }

    void removeObserver(StockObserver* observer) override {
        observers.erase(std::remove(observers.begin(), observers.end(), observer), observers.end());
    }

    void notifyObservers() override {
        for (auto observer : observers) {
            observer->update(*this);
        }
    }

    void priceUpdated(const string& symbol, double newPrice) {
        this->symbol = symbol;
        this->price = newPrice;

        cout << endl << "StockPrice: " << symbol << " updated to $" << newPrice << endl;
        notifyObservers();
    }

    string getSymbol() { return symbol; }
    double getPrice() { return price; }
};

class PriceDisplay : public StockObserver {
public:
    void update(StockPrice& stock) override {
        cout << "PriceDisplay → " << stock.getSymbol() << " is now $" << stock.getPrice() << endl;
    }
};

class AlertService : public StockObserver {
    double targetPrice;
public:
    AlertService(double targetPrice) : targetPrice(targetPrice) {}

    void update(StockPrice& stock) override {
        if (stock.getPrice() <= targetPrice) {
            cout << "AlertService → ALERT! " << stock.getSymbol() << " hit target price $" << targetPrice << endl;
        }
    }
};

class TradingBot : public StockObserver {
    double buyThreshold;
    double sellThreshold;
public:
    TradingBot(double buyThreshold, double sellThreshold) : buyThreshold(buyThreshold), sellThreshold(sellThreshold) {}

    void update(StockPrice& stock) override {
        if (stock.getPrice() <= buyThreshold) {
            cout << "TradingBot → BUY signal for " << stock.getSymbol() << " at $" << stock.getPrice() << endl;
        } else if (stock.getPrice() >= sellThreshold) {
            cout << "TradingBot → SELL signal for " << stock.getSymbol() << " at $" << stock.getPrice() << endl;
        }
    }
};

