import java.util.ArrayList;
import java.util.List;

// Observer Interface
interface WeatherObserver {
    void onWeatherUpdate(WeatherStation station);
}

// Subject
class WeatherStation {
    private double temperature;
    private double humidity;
    private double windSpeed;
    private final List<WeatherObserver> observers = new ArrayList<>();

    public void register(WeatherObserver observer) {
        observers.add(observer);
    }

    public void remove(WeatherObserver observer) {
        observers.remove(observer);
    }

    private void notifyObservers() {
        for (WeatherObserver observer : observers) {
            observer.onWeatherUpdate(this);
        }
    }

    public void updateWeather(double temp, double humidity, double windSpeed) {
        this.temperature = temp;
        this.humidity    = humidity;
        this.windSpeed   = windSpeed;
        System.out.println("\nWeatherStation: Temp=" + temp +
                           "C, Humidity=" + humidity +
                           "%, Wind=" + windSpeed + "km/h");
        notifyObservers();
    }

    public double getTemperature() { return temperature; }
    public double getHumidity()    { return humidity;    }
    public double getWindSpeed()   { return windSpeed;   }
}

// Concrete Observers
class TemperatureDisplay implements WeatherObserver {
    @Override
    public void onWeatherUpdate(WeatherStation station) {
        System.out.println("TempDisplay → Current temperature: " +
                           station.getTemperature() + "C");
    }
}

class HumidityMonitor implements WeatherObserver {
    @Override
    public void onWeatherUpdate(WeatherStation station) {
        System.out.println("HumidityMonitor → Humidity level: " +
                           station.getHumidity() + "%");
    }
}

class StormAlert implements WeatherObserver {
    @Override
    public void onWeatherUpdate(WeatherStation station) {
        if (station.getWindSpeed() > 80) {
            System.out.println("StormAlert → WARNING! High winds: " +
                               station.getWindSpeed() + "km/h");
        }
    }
}

// Client
public class Main {
    public static void main(String[] args) {
        WeatherStation station = new WeatherStation();

        TemperatureDisplay display  = new TemperatureDisplay();
        HumidityMonitor    humidity = new HumidityMonitor();
        StormAlert         alert    = new StormAlert();

        station.register(display);
        station.register(humidity);
        station.register(alert);

        station.updateWeather(22.5, 60.0, 15.0);
        station.updateWeather(19.0, 75.0, 55.0);
        station.updateWeather(15.5, 90.0, 95.0);

        System.out.println("\n--- HumidityMonitor unsubscribed ---");
        station.remove(humidity);
        station.updateWeather(14.0, 88.0, 100.0);
    }
}

