#include <bits/stdc++.h>
using namespace std;

class WeatherStation;

// Observer Interface
class WeatherObserver {
public:
    virtual void onWeatherUpdate(WeatherStation& station) = 0;
    virtual ~WeatherObserver() = default;
};

// Subject
class WeatherStation {
    double temperature = 0.0;
    double humidity = 0.0;
    double windSpeed = 0.0;
    vector<WeatherObserver*> observers;

    void notifyObservers() {
        for (auto observer : observers) {
            observer->onWeatherUpdate(*this);
        }
    }
public:
    void registerObserver(WeatherObserver* observer) {
        observers.push_back(observer);
    }

    void removeObserver(WeatherObserver* observer) {
        observers.erase(std::remove(observers.begin(), observers.end(), observer), observers.end());
    }

    void updateWeather(double temp, double hum, double wind) {
        temperature = temp;
        humidity = hum;
        windSpeed = wind;
        cout << endl << "WeatherStation: Temp=" << temp << "C, Humidity=" << hum << "%, Wind=" << wind << "km/h" << endl;
        notifyObservers();
    }

    double getTemperature() { return temperature; }
    double getHumidity() { return humidity; }
    double getWindSpeed() { return windSpeed; }
};

// Concrete Observers
class TemperatureDisplay : public WeatherObserver {
public:
    void onWeatherUpdate(WeatherStation& station) override {
        cout << "TempDisplay → Current temperature: " << station.getTemperature() << "C" << endl;
    }
};

class HumidityMonitor : public WeatherObserver {
public:
    void onWeatherUpdate(WeatherStation& station) override {
        cout << "HumidityMonitor → Humidity level: " << station.getHumidity() << "%" << endl;
    }
};

class StormAlert : public WeatherObserver {
public:
    void onWeatherUpdate(WeatherStation& station) override {
        if (station.getWindSpeed() > 80) {
            cout << "StormAlert → WARNING! High winds: " << station.getWindSpeed() << "km/h" << endl;
        }
    }
};

// Client
int main() {
    WeatherStation station;

    TemperatureDisplay display;
    HumidityMonitor humidity;
    StormAlert alert;

    station.registerObserver(&display);
    station.registerObserver(&humidity);
    station.registerObserver(&alert);

    station.updateWeather(22.5, 60.0, 15.0);
    station.updateWeather(19.0, 75.0, 55.0);
    station.updateWeather(15.5, 90.0, 95.0);

    cout << endl << "--- HumidityMonitor unsubscribed ---" << endl;
    station.removeObserver(&humidity);
    station.updateWeather(14.0, 88.0, 100.0);

    return 0;
}
